import { useCallback, useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { JxChip, JxInputField } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
}

export default function ArticleTagPicker({
  value,
  defaultValue,
  onChange,
  label = 'Ключевые слова',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue ?? []);
  const [draft, setDraft] = useState('');
  const tags = value ?? internalTags;

  const commitTags = useCallback(
    (next: string[]) => {
      if (value === undefined) {
        setInternalTags(next);
      }
      onChange?.(next);
    },
    [value, onChange],
  );

  const addTag = useCallback(() => {
    const trimmed = draft.trim();
    if (trimmed && !tags.includes(trimmed)) {
      commitTags([...tags, trimmed]);
    }
    setDraft('');
  }, [draft, tags, commitTags]);

  const removeTag = useCallback(
    (tag: string) => {
      commitTags(tags.filter((existing) => existing !== tag));
    },
    [tags, commitTags],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      commitTags(tags.slice(0, -1));
    }
  };

  const handleDraftChange = (event: ChangeEvent<HTMLInputElement>) => {
    setDraft(event.target.value);
  };

  return (
    <div>
      <JxInputField
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={handleDraftChange}
        onKeyDown={handleKeyDown}
      />
      <div
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--jx-gap, 8px)',
          marginTop: 'var(--jx-gap, 8px)',
        }}
      >
        {tags.map((tag) => (
          <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
            {tag}
          </JxChip>
        ))}
      </div>
    </div>
  );
}

